using System;
using System.Collections.Generic;
using System.Linq;
using AICad.Contracts;
using JsonUtil=AICad.Contracts.Json;
using AICad.Geometry;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.Geometry;
namespace AICad.Bridge;
internal static partial class EntityFactory {
 internal static Point3d P(Point2 p)=>new(p.X,p.Y,0);
 internal static Entity Primitive(Operation op){switch(op.Kind){case "draw_wall":return Primitive(new Operation{Kind="draw_polyline",Closed=true,Points=DraftingRules.Wall(op)});case "draw_line":return new Line(P(op.Points[0]),P(op.Points[1]));case "draw_polyline":var pl=new Polyline(op.Points.Count);try{for(int i=0;i<op.Points.Count;i++)pl.AddVertexAt(i,new Point2d(op.Points[i].X,op.Points[i].Y),0,0,0);pl.Closed=op.Closed;return pl;}catch{pl.Dispose();throw;}case "draw_circle":return new Circle(P(op.Points[0]),Vector3d.ZAxis,op.Radius);case "draw_arc":return new Arc(P(op.Points[0]),op.Radius,op.Rotation,op.Rotation+Math.PI/2);case "add_text":return new DBText{Position=P(op.Points[0]),Height=op.Height,TextString=op.Text,Rotation=op.Rotation};default:throw new CadException("UNSUPPORTED_TOOL",op.Kind);}}
 internal static IEnumerable<Entity> Preview(Operation op,TemplateProfile template){if(op.Kind!="insert_block"){yield return Primitive(op);yield break;}var matrix=Matrix3d.Displacement(P(op.Points[0])-Point3d.Origin)*Matrix3d.Rotation(op.Rotation,Vector3d.ZAxis,Point3d.Origin);foreach(var child in template.Blocks.Single(b=>b.Id==op.AssetId).Geometry){var e=Primitive(child);try{e.TransformBy(matrix);}catch{e.Dispose();throw;}yield return e;}}
 internal static Entity Append(Operation op,DrawingPlan plan,Database db,Transaction tx){if(op.Kind!="insert_block")return Primitive(op);var asset=plan.Template.Blocks.Single(b=>b.Id==op.AssetId);string name="AICAD_"+asset.Id+"_"+JsonUtil.Hash(asset).Substring(0,12);var bt=(BlockTable)tx.GetObject(db.BlockTableId,OpenMode.ForRead);ObjectId def;if(bt.Has(name)){def=bt[name];var existing=(BlockTableRecord)tx.GetObject(def,OpenMode.ForRead);if(existing.ExtensionDictionary.IsNull)throw new CadException("ASSET_COLLISION","Existing block has no verified AICAD signature.");var dictionary=(DBDictionary)tx.GetObject(existing.ExtensionDictionary,OpenMode.ForRead);if(!dictionary.Contains("AICAD_HASH")||((Xrecord)tx.GetObject(dictionary.GetAt("AICAD_HASH"),OpenMode.ForRead)).Data.AsArray()[0].Value.ToString()!=JsonUtil.Hash(asset))throw new CadException("ASSET_COLLISION","Block definition differs from snapshot.");}else if(asset.NativeSource!=null){def=NativeLibraryAssets.Clone(asset,db,tx,name);}else{bt.UpgradeOpen();var block=new BlockTableRecord{Name=name};def=bt.Add(block);tx.AddNewlyCreatedDBObject(block,true);foreach(var child in asset.Geometry){var e=Primitive(child);block.AppendEntity(e);tx.AddNewlyCreatedDBObject(e,true);e.Layer="0";}block.CreateExtensionDictionary();var dict=(DBDictionary)tx.GetObject(block.ExtensionDictionary,OpenMode.ForWrite);var hash=new Xrecord{Data=new ResultBuffer(new TypedValue((int)DxfCode.Text,JsonUtil.Hash(asset)))};dict.SetAt("AICAD_HASH",hash);tx.AddNewlyCreatedDBObject(hash,true);}return new BlockReference(P(op.Points[0]),def){Rotation=op.Rotation,ScaleFactors=new Scale3d(op.SymbolScale??1)};}
 internal static void DemandBounds(Entity entity,DrawingPlan plan){var ext=entity.GeometricExtents;if(Math.Abs(ext.MinPoint.Z)>1e-6||Math.Abs(ext.MaxPoint.Z)>1e-6)throw new CadException("OUTSIDE_SCOPE","Entity is not planar.");foreach(var p in new[]{new Point2(ext.MinPoint.X,ext.MinPoint.Y),new Point2(ext.MaxPoint.X,ext.MinPoint.Y),new Point2(ext.MaxPoint.X,ext.MaxPoint.Y),new Point2(ext.MinPoint.X,ext.MaxPoint.Y)})if(!Validation.Contains(plan.Scope,p))throw new CadException("OUTSIDE_SCOPE","Native entity extents exceed task scope.");}
}
